    {
      "clauseType": "other",
      "excerpt": "This Data Analytics Consulting Agreement is entered into as of February 5, 2026 by and between Harborview Logistics Corp. (\"Client\") and Samuel Ortiz, an independent data analytics consultant (\"Consultant\")."
    },
    {
      "clauseType": "other",
      "excerpt": "Consultant shall analyze Client's shipment data and deliver a quarterly performance report identifying operational efficiencies, as described in Exhibit A."
    },
    {
      "clauseType": "payment_terms",
      "excerpt": "Client shall pay Consultant a fixed fee of $12,000 per quarter, invoiced at the start of each quarter, due within thirty (30) days of invoice. Any amount not paid within thirty (30) days of the due date shall accrue interest at 1% per month."
    },
    {
      "clauseType": "auto_renewal",
      "excerpt": "This Agreement shall continue for successive quarterly terms unless terminated."
    },
    {
      "clauseType": "termination",
      "excerpt": "Either party may terminate this Agreement for convenience upon thirty (30) days' prior written notice, or immediately for material breach that remains uncured for fifteen (15) days after written notice."
    },
    {
      "clauseType": "ip_assignment",
      "excerpt": "Upon payment, all reports and analyses created specifically for Client under this Agreement shall be assigned to Client. Consultant retains ownership of Consultant's underlying analytical methods, scripts, and tools used to produce the deliverables, and grants Client a perpetual license to use them solely as incorporated into the delivered reports."
    },
    {
      "clauseType": "confidentiality",
      "excerpt": "Each party shall protect the other party's confidential information from unauthorized disclosure for a period of three (3) years following disclosure, excluding information that is or becomes publicly available, or that the receiving party already knew prior to disclosure, through no fault of its own."
    },
    {
      "clauseType": "liability",
      "excerpt": "Each party's total liability under this Agreement shall not exceed the total fees paid in the twelve (12) months preceding the claim, and neither party shall be liable for indirect, incidental, or consequential damages."
    },
    {
      "clauseType": "indemnification",
      "excerpt": "Each party shall indemnify the other party against third-party claims arising from that party's own breach of this Agreement or negligent acts, provided that neither party's indemnification obligation shall exceed the limitation of liability set forth above."
    }
  ]
}

